package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
final class KnowledgeReviewsAcceptance {
 static String api(String id){return "/api/openservice/knowledge/"+id+"/review";}
 static Map<String,Object> view(WorkflowSupport h,String id,String actor)throws Exception {var response=h.get(api(id),auth(actor));assertEquals(200,response.statusCode(),html(response));return result(response);}
 static Map<String,Object> body(Map<String,Object> view,String op,Map<String,Object> extra){var body=map("operation",op,"review",view.get("review"),"confirm",true);body.putAll(extra);return body;}
 static Map<String,Object> act(WorkflowSupport h,String id,String actor,String op,Map<String,Object> extra)throws Exception {var response=h.json("POST",api(id),body(view(h,id,actor),op,extra),auth(actor));assertEquals(200,response.statusCode(),html(response));return result(response);}
 static String accountId(Store store,String name)throws Exception {try(var db=store.open()){return RecordAccess.owner(db,name);}}
 static String seed(WorkflowSupport h)throws Exception {h.account("KnowledgeReviewer","admin");String id=KnowledgeDraftsAcceptance.seed(h.store);act(h,id,"admin","configure",map("reviewer_id",accountId(h.store,"KnowledgeReviewer")));return id;}
 static int direct(WorkflowSupport h,String id,String actor,String intent)throws Exception {return h.json("POST","/api/openservice/operations/knowledge/"+id,map("operation",intent),auth(actor)).statusCode();}
 static void approve(WorkflowSupport h,String id,String intent)throws Exception {act(h,id,"admin","submit",map("intent",intent));act(h,id,"KnowledgeReviewer","approve",map("reason","Reviewed current content <script>"));}
 static void run(WorkflowSupport h)throws Exception {
  String id=seed(h);h.account("KnowledgeReader","reader");assertEquals(409,direct(h,id,"admin","publish"));var pending=act(h,id,"admin","submit",map("intent","publish"));assertEquals("pending",object(pending.get("request")).get("status"));assertEquals("Current instructions",object(result(h.get("/api/openservice/knowledge/"+id,auth("KnowledgeReader"))).get("article")).get("content"));assertEquals(false,pending.get("can_decide"));assertEquals(true,view(h,id,"KnowledgeReviewer").get("can_decide"));var approved=act(h,id,"KnowledgeReviewer","approve",map("reason","Reviewed"));assertEquals("approved",object(approved.get("request")).get("status"));assertEquals(false,approved.get("can_apply"));assertEquals(true,view(h,id,"admin").get("can_apply"));new Store(h.environment);var applied=act(h,id,"admin","apply",map());assertEquals("applied",object(applied.get("request")).get("status"));assertEquals("Unpublished work",object(result(h.get("/api/openservice/knowledge/"+id,auth("KnowledgeReader"))).get("article")).get("content"));assertEquals(409,direct(h,id,"admin","publish"));
  assertEquals(409,direct(h,id,"admin","retire"));act(h,id,"admin","submit",map("intent","retire"));act(h,id,"KnowledgeReviewer","reject",map("reason","Keep available"));assertEquals(409,direct(h,id,"admin","retire"));assertEquals(200,h.get("/api/openservice/knowledge/"+id,auth("KnowledgeReader")).statusCode());approve(h,id,"retire");act(h,id,"admin","apply",map());assertEquals(404,h.get("/api/openservice/knowledge/"+id,auth("KnowledgeReader")).statusCode());assertEquals(0,objects(parsed(h.get("/api/openservice/knowledge?q=Current",auth("KnowledgeReader"))).get("result")).size());approve(h,id,"publish");assertEquals(200,direct(h,id,"admin","publish"));try(var db=h.store.open()){assertEquals(4,db.count("SELECT COUNT(*) FROM os_publication WHERE article_id=?",id));assertEquals(3,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='knowledge.review_applied'"));}
 }
 static void stale(WorkflowSupport h)throws Exception {
  String id=seed(h);approve(h,id,"publish");var old=view(h,id,"admin");assertEquals(200,h.json("PATCH","/api/now/table/kb_knowledge/"+id,map("text","Changed after approval"),auth("admin")).statusCode());assertEquals(409,h.json("POST",api(id),body(old,"apply",map()),auth("admin")).statusCode());assertEquals(false,view(h,id,"admin").get("current"));assertEquals(409,direct(h,id,"admin","publish"));approve(h,id,"publish");assertEquals(409,direct(h,id,"KnowledgeReviewer","publish"));assertEquals(409,direct(h,id,"admin","retire"));assertEquals(400,h.json("POST","/api/openservice/operations/knowledge/"+id,map("operation","restore","version",1),auth("admin")).statusCode());
  var draft=KnowledgeDraftsAcceptance.result(h.get(KnowledgeDraftsAcceptance.api(id),auth("admin")));assertEquals(200,h.json("POST",KnowledgeDraftsAcceptance.api(id),KnowledgeDraftsAcceptance.action(draft,"publish"),auth("admin")).statusCode());approve(h,id,"publish");String reviewer=accountId(h.store,"KnowledgeReviewer");try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",reviewer);db.connection.commit();}assertEquals(409,direct(h,id,"admin","publish"));approve(h,id,"publish");act(h,id,"admin","configure",map("reviewer_id",reviewer));assertTrue(object(view(h,id,"admin").get("request")).isEmpty());assertEquals(409,direct(h,id,"admin","publish"));act(h,id,"admin","configure",map("reviewer_id",""));assertEquals(200,direct(h,id,"admin","publish"));assertEquals(200,h.json("POST","/api/openservice/operations/knowledge/"+id,map("operation","restore","version",1),auth("admin")).statusCode());assertEquals(200,direct(h,id,"admin","retire"));
 }
 static void validation(WorkflowSupport h)throws Exception {
  String id=seed(h);h.account("KnowledgeAgent","agent");h.account("KnowledgeOther","admin");assertEquals(401,h.get(api(id),null).statusCode());assertEquals(403,h.get(api(id),auth("KnowledgeAgent")).statusCode());assertEquals(403,h.json("POST",api(id),map(),auth("KnowledgeAgent")).statusCode());assertEquals(405,h.json("PUT",api(id),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(id)+"?x=1",auth("admin")).statusCode());assertEquals(400,h.get(api(id)+"?x=1&x=2",auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());var view=view(h,id,"admin");for(var bad:List.of(map(),body(view,"unknown",map()),body(view,"submit",map("intent","bad")),body(view,"configure",map("reviewer_id",4)),body(view,"configure",map("reviewer_id",id())),body(view,"configure",map("reviewer_id",accountId(h.store,"KnowledgeAgent"))))){assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());}var bad=body(view,"submit",map("intent","publish"));bad.put("confirm",false);assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());bad.put("confirm",true);bad.put("extra",true);assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());assertEquals(400,h.json("POST",api(id),body(view(h,id,"KnowledgeReviewer"),"submit",map("intent","publish")),auth("KnowledgeReviewer")).statusCode());
  act(h,id,"admin","submit",map("intent","publish"));assertEquals(409,h.json("POST",api(id),body(view(h,id,"admin"),"approve",map("reason","Self")),auth("admin")).statusCode());assertEquals(409,h.json("POST",api(id),body(view(h,id,"KnowledgeOther"),"reject",map("reason","Other")),auth("KnowledgeOther")).statusCode());for(String reason:List.of(" ","x".repeat(2001)))assertEquals(400,h.json("POST",api(id),body(view(h,id,"KnowledgeReviewer"),"approve",map("reason",reason)),auth("KnowledgeReviewer")).statusCode());act(h,id,"KnowledgeReviewer","approve",map("reason","Good"));assertEquals(409,h.json("POST",api(id),body(view(h,id,"KnowledgeReviewer"),"approve",map("reason","Again")),auth("KnowledgeReviewer")).statusCode());assertEquals(409,h.json("POST",api(id),body(view(h,id,"KnowledgeReviewer"),"apply",map()),auth("KnowledgeReviewer")).statusCode());String browser="/admin/knowledge/"+id+"/review";assertEquals(403,h.form(browser,body(view(h,id,"admin"),"apply",map()),auth("admin")).statusCode());var form=body(view(h,id,"admin"),"apply",map());form.put("confirm","false");assertEquals(400,h.protectedForm(browser,form,auth("admin")).statusCode());form.put("confirm","true");assertEquals(302,h.protectedForm(browser,form,auth("admin")).statusCode());
 }
 static void concurrency(WorkflowSupport h)throws Exception {String id=seed(h);approve(h,id,"publish");var body=body(view(h,id,"admin"),"apply",map());try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->h.json("POST",api(id),body,auth("admin")).statusCode());var b=pool.submit(()->h.json("POST",api(id),body,auth("admin")).statusCode());assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}try(var db=h.store.open()){assertEquals(3,db.count("SELECT COUNT(*) FROM os_publication WHERE article_id=?",id));}} static void authority(WorkflowSupport h)throws Exception {
  String id=seed(h),reviewer=accountId(h.store,"KnowledgeReviewer"),requester=accountId(h.store,"admin");
  for(String change:List.of("active=0","role='reader'","password_reset_required=1","auth_revision=auth_revision+1")){
   approve(h,id,"publish");try(var db=h.store.open()){db.update("UPDATE os_user SET "+change+" WHERE user_id=?",reviewer);db.connection.commit();}assertEquals(false,view(h,id,"admin").get("current"));assertEquals(409,direct(h,id,"admin","publish"));assertEquals(change.startsWith("auth_revision")?200:400,h.json("POST",api(id),body(view(h,id,"admin"),"submit",map("intent","publish")),auth("admin")).statusCode());
   try(var db=h.store.open()){db.update("UPDATE os_user SET active=1,role='admin',password_reset_required=0 WHERE user_id=?",reviewer);db.connection.commit();}
  }
  approve(h,id,"publish");try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",requester);db.connection.commit();}assertEquals(false,view(h,id,"KnowledgeReviewer").get("current"));assertEquals(409,direct(h,id,"admin","publish"));approve(h,id,"publish");try(var db=h.store.open()){PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"kb_knowledge",id),db.viewerId,map("visibility","private","owner_id",db.viewerId));db.connection.commit();}assertEquals(400,h.json("POST",api(id),body(view(h,id,"admin"),"submit",map("intent","publish")),auth("admin")).statusCode());assertEquals(false,view(h,id,"KnowledgeReviewer").get("current"));
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"kb_knowledge",id),db.viewerId,map("visibility","workspace","owner_id",""));db.connection.commit();}approve(h,id,"publish");Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"kb_knowledge");var changed=new LinkedHashMap<>(schema);changed.put("label","Changed schema");db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='kb_knowledge'",JSON.writeValueAsString(changed));db.connection.commit();}try{assertEquals(409,direct(h,id,"admin","publish"));for(String operation:List.of("read","update")){try(var db=h.store.open()){var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map(operation,List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='kb_knowledge'",JSON.writeValueAsString(denied));db.connection.commit();}assertEquals(403,h.get(api(id),auth("admin")).statusCode());}}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='kb_knowledge'",JSON.writeValueAsString(schema));db.connection.commit();}}
 }
 static void lifecycle(WorkflowSupport h)throws Exception {
  h.account("KnowledgeReviewer","admin");String id;try(var db=h.store.open()){PlatformFoundationTest.bind(db);id=Service.create(db,"kb_knowledge",map("short_description","New article","text","First body"),"admin").get("sys_id").toString();db.connection.commit();}assertTrue(object(view(h,id,"admin").get("latest")).isEmpty());assertEquals(400,h.json("POST",api(id),body(view(h,id,"admin"),"submit",map("intent","publish")),auth("admin")).statusCode());act(h,id,"admin","configure",map("reviewer_id",accountId(h.store,"KnowledgeReviewer")));assertEquals(400,h.json("POST",api(id),body(view(h,id,"admin"),"submit",map("intent","retire")),auth("admin")).statusCode());approve(h,id,"publish");act(h,id,"admin","apply",map());approve(h,id,"retire");assertEquals(200,direct(h,id,"admin","retire"));assertEquals(400,h.json("POST",api(id),body(view(h,id,"admin"),"submit",map("intent","retire")),auth("admin")).statusCode());approve(h,id,"publish");try(var db=h.store.open()){db.update("UPDATE os_record SET data="+db.jsonParameter()+" WHERE sys_id=?",JSON.writeValueAsString(map("short_description","New article","text","")),id);db.connection.commit();}assertEquals(400,h.json("POST",api(id),body(view(h,id,"admin"),"submit",map("intent","publish")),auth("admin")).statusCode());
 }

 static void rollback(WorkflowSupport h)throws Exception {
  String id=seed(h);try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("UPDATE os_user SET password_reset_required=1 WHERE user_id=?",db.viewerId);var view=KnowledgeReviews.page(db,id);assertEquals(400,assertThrows(Failure.class,()->KnowledgeReviews.act(db,id,body(view,"submit",map("intent","publish")))).status);db.connection.rollback();}
  try(var db=h.store.open()){db.update("UPDATE os_publication SET version=2147483647 WHERE article_id=? AND version=2",id);db.connection.commit();}approve(h,id,"publish");assertEquals(400,direct(h,id,"admin","publish"));assertEquals("approved",object(view(h,id,"admin").get("request")).get("status"));try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_publication WHERE article_id=?",id));assertEquals(0,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='knowledge.review_applied'"));}
 }

}
